{
  "a_sentences": [
    {
      "a_text": "Le Tribunal fédéral rappelle que la personne assurée et l'invalidité sont définies aux art. 7 et 8 LPGA, et que le droit à la rente d'invalidité est régi par les art. 28 al. 1 et art. 28a ss LAI.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Il précise également que le taux d'invalidité se détermine selon la méthode générale de comparaison des revenus prévue à l'art. 16 LPGA.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Le Tribunal fédéral indique que l'octroi de l'aide au placement ne requiert pas une invalidité importante, un degré relativement faible de difficultés liées à l'état de santé suffisant pour fonder le droit à cette mesure.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Pour le revenu sans invalidité, la juridiction cantonale s'est fondée sur le salaire effectivement perçu en 2020 par la personne assurée avant l'incapacité de travail due au infarctus.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "La personne assurée conteste ce point et soutient que le revenu sans invalidité devrait inclure son activité accessoire exercée avant l'accident de 2010.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Le Tribunal fédéral rejette ce grief et confirme que l'intimée n'a pas violé le droit fédéral en ne retenant pas le revenu accessoire, estimant que la personne assurée l'aurait abandonné même en bonne santé.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Le Tribunal fédéral admet le recours en ce qui concerne l'aide au placement et renvoie la cause à l'intimée pour qu'elle examine à nouveau ce droit.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "En revanche, le Tribunal fédéral confirme le rejet du recours concernant le taux de la rente d'invalidité.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Considérant que la cause est renvoyée à l'administration pour instruction complémentaire, le Tribunal fédéral qualifie ce renvoi de gain de cause complet au sens de la jurisprudence.",
      "b_propositions": ["P8"]
    }
  ]
}
